import type { ComponentPropsWithoutRef } from "react";
import { cn } from "../../lib/cn";
import "../../styles/skeleton.css";

export type SkeletonProps = ComponentPropsWithoutRef<"span">;

/**
 * Placeholder for loading content. Decorative, so it is hidden from assistive
 * tech. Put aria-busy on the region and announce loading elsewhere.
 */
export function Skeleton({ className, ...props }: SkeletonProps) {
  return <span aria-hidden="true" className={cn("eui-skeleton", className)} {...props} />;
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Skeleton. A soft opacity pulse. No layout change, and no pulse when reduced motion is on. */

.eui-skeleton {
  display: block;
  width: 100%;
  height: 1em;
  border-radius: var(--eui-radius-sm);
  background-color: var(--eui-color-hover);
  animation: eui-skeleton-pulse 1.6s var(--eui-easing-out) infinite;
}

@keyframes eui-skeleton-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.55;
  }
}

@media (prefers-reduced-motion: reduce) {
  .eui-skeleton {
    animation: none;
  }
}
